var i=`1170-sopes`;var n=`world-1170`;var t=`MX`;var s=`central-america-caribbean`;var o=8;var r=48;var l={en:`Sopes`,ua:`Сопес`};var d={en:`Sopes is a dish from Mexico prepared with masa harina, canned black beans, queso fresco, lettuce. This is a home-scale version with measured ingredients in the individual steps where they are used. Canned black beans mashed in a pan replace prepared refried beans.`,ua:`Сопес, страва кухні країни Мексика, яку готують із таких продуктів: маса харіна, консервована чорна квасоля, кесо фреско, салат латук. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Консервована чорна квасоля, розім’ята на сковороді, замінює готову пересмажену квасолю.`};var p=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`masa-harina`,450,`g`],[`water`,360,`ml`],[`table-salt`,6,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`canola-oil`,65,`ml`]]},{en:`Warm and mash the drained canned black beans with a little oil to make a thick spread before topping the formed sopes.`,ua:`Прогрійте й розімніть злиту консервовану чорну квасолю з невеликою кількістю олії до густої намазки для сопес.`,t:[`chopping`,`sauteing`],m:7,i:[[`canned-black-beans`,300,`g`],[`canola-oil`,20,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`queso-fresco`,150,`g`],[`lettuce`,180,`g`],[`red-salsa`,140,`g`]]}];var h={slug:i,id:n,country:`MX`,region:s,servings:8,minutes:48,title:l,text:d,steps:p};export{t as country,h as default,n as id,r as minutes,s as region,o as servings,i as slug,p as steps,d as text,l as title};